import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def build_list(vals):
    if not vals: return None, []
    head = N(vals[0])
    nodes = [head]
    for v in vals[1:]:
        nodes[-1].nxt = N(v)
        nodes.append(nodes[-1].nxt)
    return head, nodes

def build_lists(valsA, valsB, has, skipA, skipB):
    headA, na = build_list(valsA)
    headB, nb = build_list(valsB)
    if has and skipA < len(na) and skipB < len(nb):
        common = na[skipA]
        if skipB > 0:
            nb[skipB - 1].nxt = common
        else:
            headB = common
    return headA, headB

def intersection_brute(headA, headB):
    seen = set()
    cur = headA
    while cur:
        seen.add(id(cur))
        cur = cur.nxt
    cur = headB
    while cur:
        if id(cur) in seen:
            return cur.v
        cur = cur.nxt
    return -1

if __name__ == '__main__':
    data = sys.stdin.read().split()
