    if nA == 0:
        valsA = []
        idx = 1
    else:
        valsA = list(map(int, data[1:1 + nA]))
        idx = 1 + nA
    nB = int(data[idx]); idx += 1
    if nB == 0:
        valsB = []
        idx += 1
    else:
        valsB = list(map(int, data[idx:idx + nB]))
        idx += nB
    has = int(data[idx]); idx += 1
    if has:
        skipA, skipB = int(data[idx]), int(data[idx + 1])
    else:
        skipA = skipB = 0
    a, b = build_lists(valsA, valsB, has, skipA, skipB)
    print(intersection_brute(a, b))

