def length(node):
    n = 0
    while node:
        n += 1
        node = node.nxt
    return n

def intersection_opt(headA, headB):
    a, b = headA, headB
    la, lb = length(a), length(b)
    if la > lb:
        for _ in range(la - lb):
            a = a.nxt
    else:
        for _ in range(lb - la):
            b = b.nxt
    while a and b:
        if a is b:
            return a.v
        a = a.nxt
        b = b.nxt
    return -1

